import json,re;d=json.load(open('$OPENCLAW_CONFIG_PATH'))
def red(o):
  if isinstance(o,dict): return {k:('***' if re.search('key|token|secret|password',k,re.I) else red(v)) for k,v in o.items()}
  if isinstance(o,list): return [red(x) for x in o]
  return o
print(json.dumps(red(d),indent=1))"

