// Minimal stdio MCP client: spawns the exact command registered in OpenClaw.
import { spawn } from 'node:child_process';
const [cmd, ...rest] = process.argv.slice(2);
const calls = JSON.parse(rest.pop());
const p = spawn(cmd, rest, { env: { ...process.env, GBRAIN_HOME: '/harness-state' }, cwd: '/tmp', stdio: ['pipe', 'pipe', 'pipe'] });
let buf = ''; const waiters = new Map(); let id = 0;
p.stdout.on('data', d => { buf += d; let i; while ((i = buf.indexOf('\n')) >= 0) { const line = buf.slice(0, i); buf = buf.slice(i + 1); if (!line.trim()) continue; try { const m = JSON.parse(line); if (m.id != null && waiters.has(m.id)) { waiters.get(m.id)(m); waiters.delete(m.id); } } catch {} } });
p.stderr.on('data', () => {});
const rpc = (method, params) => new Promise(r => { const i = ++id; waiters.set(i, r); p.stdin.write(JSON.stringify({ jsonrpc: '2.0', id: i, method, params }) + '\n'); });
const init = await rpc('initialize', { protocolVersion: '2025-06-18', capabilities: {}, clientInfo: { name: 'install-check', version: '1' } });
console.log('server:', JSON.stringify(init.result?.serverInfo));
p.stdin.write(JSON.stringify({ jsonrpc: '2.0', method: 'notifications/initialized' }) + '\n');
const tl = await rpc('tools/list', {});
console.log('tools:', tl.result.tools.map(t => t.name).join(', '));
for (const [name, args] of calls) {
  const r = await rpc('tools/call', { name, arguments: args });
  const text = (r.result?.content || []).map(c => c.text).join('\n');
  console.log(`\n== ${name}(${JSON.stringify(args)}) isError=${!!r.result?.isError} ${r.error ? JSON.stringify(r.error) : ''}`);
  console.log(text.slice(0, 1500));
}
p.kill();

